<script setup>
import {computed} from 'vue';import {router,usePage} from '@inertiajs/vue3';import PortalLayout from '../../../Layouts/PortalLayout.vue';
defineProps({series:Object});const page=usePage();const hi=computed(()=>page.props.locale==='hi');
function enroll(id,paid=false){if(confirm(paid?(hi.value?'सुरक्षित भुगतान शुरू करें?':'Continue to secure payment?'):(hi.value?'इस टेस्ट सीरीज़ में शामिल हों?':'Enroll in this test series?')))router.post(paid?('/student/test-series/'+id+'/checkout'):('/student/test-series/'+id+'/enroll'));}
</script>
<template><PortalLayout portal="student" :title="hi?'टेस्ट सीरीज़':'Test series'" :subtitle="hi?'अपनी तैयारी के लिए फ्री और पेड टेस्ट पैकेज चुनें।':'Explore curated free and paid examination packages.'">
<div class="grid gap-4 md:grid-cols-2"><article v-for="s in series.data" :key="s.id" class="rounded-2xl border bg-white p-5"><div class="flex items-start justify-between gap-3"><h2 class="text-lg font-extrabold">{{s.title}}</h2><span class="rounded-full px-3 py-1 text-xs font-bold" :class="s.access_type==='paid'?'bg-amber-100 text-amber-800':'bg-emerald-100 text-emerald-800'">{{s.access_type==='paid'?s.currency+' '+s.price:(hi?'मुफ्त':'FREE')}}</span></div><p class="mt-2 min-h-10 text-sm text-slate-600">{{s.description}}</p><p class="mt-3 text-xs text-slate-500">{{s.exams_count}} {{hi?'परीक्षाएँ':'exams'}}</p>
<div class="mt-4 flex items-center justify-between border-t pt-3"><span class="text-sm font-semibold" :class="s.enrollment?.status==='active'?'text-emerald-700':'text-slate-500'">{{s.enrollment?.status==='active'?(hi?'नामांकित':'Enrolled'):s.enrollment?.status==='pending_payment'?(hi?'भुगतान लंबित':'Payment pending'):(hi?'उपलब्ध':'Available')}}</span><button v-if="s.enrollment?.status!=='active'" @click="enroll(s.id,s.access_type==='paid')" class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">{{s.access_type==='paid'?(hi?'भुगतान करें':'Pay & enroll'):(hi?'जुड़ें':'Enroll')}}</button><a v-else href="/student/my-test-series" class="text-sm font-bold text-indigo-700">{{hi?'मेरी सीरीज़':'Open my series'}}</a></div></article>
<p v-if="!series.data.length" class="rounded-xl border bg-white p-8 text-center text-slate-500 md:col-span-2">{{hi?'अभी कोई टेस्ट सीरीज़ उपलब्ध नहीं है।':'No test series available right now.'}}</p></div></PortalLayout></template>